#nullable enable

using System.Collections.Concurrent;
using StockFeed.Contracts;   // StockNoticed — the model-declared foreign event

namespace StockFeed.Landing;

/// <summary>
/// THE ONE THING A REFERENCE IMPLEMENTATION CANNOT HONESTLY OWN: the other system. In a real project this
/// class is deleted and <see cref="IWarehouseFeed"/> is implemented over their HTTP API, their SDK, or a
/// database view they expose.
///
/// It lives in the application rather than in the test project on purpose. Mechanism C is the only landing
/// choice whose correctness depends on something outside our process answering a query, so a stub the running
/// app can be pointed at is what makes "run it and look" possible for the poll at all — and running it is the
/// only way any of these mechanisms has ever been proved.
///
/// A sequence-ordered snapshot, not a queue: <see cref="NoticesAfter"/> is a QUERY and must be safe to ask
/// twice. That is exactly what a real feed's "give me everything after N" endpoint is, and it is what lets the
/// poll clock crash and recover without losing anything. A stub that popped items off a queue would make the
/// mechanism look durable when the durability was the stub's.
/// </summary>
public sealed class InMemoryWarehouseFeed : IWarehouseFeed
{
    private readonly ConcurrentDictionary<Guid, StockNoticed> _notices = new();

    /// <summary>What the warehouse would have recorded. Idempotent on notice id, as theirs would be.</summary>
    public void Publish(StockNoticed notice) => _notices[notice.NoticeId] = notice;

    public Task<IReadOnlyList<StockNoticed>> NoticesAfter(long afterSequence, CancellationToken cancellation)
        => Task.FromResult<IReadOnlyList<StockNoticed>>(
            _notices.Values
                .Where(n => n.Sequence > afterSequence)
                .OrderBy(n => n.Sequence)
                .ToList());
}
